        {field('pot', 'Pot')}{' '}
        {field('alert-threshold', 'Alert threshold')}{' '}
        {field('fiscal-start-month', 'Fiscal year start month (1 to 12)', 'numeric')}{' '}
        {field('parent', 'Parent sheet', 'text')}{' '}
        {PERM_ACTIONS.map((a) => (
